// --- algo_lib.FDb.DigitChar.Match
inline bool algo_lib::DigitCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('0')) < u32(10);
    return ret;
}

// --- algo_lib.FDb.NewLineChar.Match
inline bool algo_lib::NewLineCharQ(u32 ch) {
    bool ret = false;
    ret |= ch == '\n';
    ret |= ch == '\r';
    return ret;
}

// --- algo_lib.FDb.WhiteChar.Match
inline bool algo_lib::WhiteCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('\t')) < u32(2);
    ret |= ch == '\r';
    ret |= ch == ' ';
    return ret;
}

// --- algo_lib.FDb.DirSep.Match
inline bool algo_lib::DirSepQ(u32 ch) {
    bool ret = false;
    ret |= ch == '/';
    ret |= ch == '\\';
    return ret;
}

// --- algo_lib.FDb.IdentChar.Match
inline bool algo_lib::IdentCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('0')) < u32(10);
    ret |= (ch - u32('A')) < u32(26);
    ret |= ch == '_';
    ret |= (ch - u32('a')) < u32(26);
    return ret;
}

// --- algo_lib.FDb.IdentStart.Match
inline bool algo_lib::IdentStartQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('A')) < u32(26);
    ret |= ch == '_';
    ret |= (ch - u32('a')) < u32(26);
    return ret;
}

// --- algo_lib.FDb.AlphaChar.Match
inline bool algo_lib::AlphaCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('A')) < u32(26);
    ret |= (ch - u32('a')) < u32(26);
    return ret;
}

// --- algo_lib.FDb.HexChar.Match
inline bool algo_lib::HexCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('0')) < u32(10);
    ret |= (ch - u32('A')) < u32(6);
    ret |= (ch - u32('a')) < u32(6);
    return ret;
}

// --- algo_lib.FDb.UpperChar.Match
inline bool algo_lib::UpperCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('A')) < u32(26);
    return ret;
}

// --- algo_lib.FDb.CmdLineNameBreak.Match
inline bool algo_lib::CmdLineNameBreakQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('\t')) < u32(2);
    ret |= ch == '\r';
    ret |= ch == ' ';
    ret |= (ch - u32('(')) < u32(2);
    ret |= ch == ':';
    ret |= ch == '[';
    ret |= ch == ']';
    ret |= ch == '{';
    ret |= ch == '}';
    return ret;
}

// --- algo_lib.FDb.CmdLineValueBreak.Match
inline bool algo_lib::CmdLineValueBreakQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('\t')) < u32(2);
    ret |= ch == '\r';
    ret |= ch == ' ';
    ret |= (ch - u32('(')) < u32(2);
    ret |= ch == '[';
    ret |= ch == ']';
    ret |= ch == '{';
    ret |= ch == '}';
    return ret;
}

// --- algo_lib.FDb.WordSeparator.Match
inline bool algo_lib::WordSeparatorQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('\t')) < u32(2);
    ret |= ch == '\r';
    ret |= (ch - u32(' ')) < u32(16);
    ret |= ch == ';';
    ret |= ch == '=';
    ret |= (ch - u32('?')) < u32(2);
    ret |= ch == '[';
    ret |= (ch - u32(']')) < u32(2);
    ret |= ch == '`';
    ret |= (ch - u32('{')) < u32(4);
    return ret;
}

// --- algo_lib.FDb.LowerChar.Match
inline bool algo_lib::LowerCharQ(u32 ch) {
    bool ret = false;
    ret |= (ch - u32('a')) < u32(26);
    return ret;
}

